import re, sys, json
from pathlib import Path
P,O=Path(sys.argv[1]),Path(sys.argv[2])
RX=re.compile(r"\b(R-\d+|REQ-\d+|SPEC-\d+|T-\d+)\b")
spec=(P/"spec.md").read_text().splitlines(); tl=(P/"proposed.md").read_text().splitlines()
R=[]; 
for n,l in enumerate(spec,1):
    for m in RX.findall(l):
        if not m.startswith("T-") and m not in [r["id"] for r in R]: R.append({"id":m,"line":n})
tasks=[]; cur=None
for n,l in enumerate(tl,1):
    if l.startswith("## "):
        ids=RX.findall(l); cur={"task":ids[0],"refs":ids[1:],"line":n,"text":l}; tasks.append(cur)
    elif cur and l.strip(): cur["text"]+=" "+l.strip()
rows=[]
for r in R:
    m=sorted(t["task"] for t in tasks if re.search(r"\b%s\b"%re.escape(r["id"]),t["text"]) )
    rows.append({"requirement_id":r["id"],"spec_cite":f"spec.md:{r['line']}","matched_task_ids":m,"match_method":"exact" if m else "none","source":"parsed"})
matched=sum(1 for r in rows if r["matched_task_ids"])
res={"pass1_parsed_ids":[r["id"] for r in R],"tasks":[t["task"] for t in tasks],"total_tasks":len(tasks),"matrix":rows,"coverage_pct":round(matched/len(rows),4),"unmapped_requirements":[r["requirement_id"] for r in rows if not r["matched_task_ids"]]}
(O/"artifacts/coverage-pass1.json").write_text(json.dumps(res,indent=2)+"\n"); print(json.dumps(res,indent=2))
EOF

